'use strict';
const methods = {
  swiss: {name:'Swiss-derived', subtitle:'Minimum-flow example · candidate floor', color:'#a26422', icon:'—', caption:'A low-flow statistic enters a graduated conversion. The resulting floor is a different quantity; any additions need their own basis.', caveat:'Concept only. No source-exact Swiss statutory table is calculated here. Uzbekistan table coefficients and applicable additions are not supplied.'},
  kazakh: {name:'Kazakh-style', subtitle:'Seasonal-flow example · conditional candidate', color:'#26709a', icon:'∿', caption:'Choose an annual exceedance class, shift it once, then distribute the candidate volume through a seasonal shape.', caveat:'The illustrated 50 → 75 shift concerns ranked annual volumes, not 75% of today’s runoff. No reference series, bounds, risk operand or accepted shape is calculated in this preview.'},
  site: {name:'Site study', subtitle:'Habitat example · one top-tier component', color:'#56815d', icon:'⌒', caption:'A supplied habitat response can favour a range of flows. More water does not always mean more suitable habitat.', caveat:'Conceptual curve and reach sketch only. No hydraulic fields, calibrated weighted usable area, actual-flow marker or biological outcome is available. This is not a complete top-tier regime.'}
};
const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const params = new URLSearchParams(location.search);
const allowed = (key, options, fallback) => options.includes(params.get(key)) ? params.get(key) : fallback;
const state = {lang:PrototypeLocale.language,operation:allowed('operation',['ecology','irrigation'],'ecology'), basis:allowed('basis',['matched','fixed'],'matched'), view:allowed('view',['compare','system','assessment','route'],'compare'), forcing:allowed('forcing',['normal','dry'],'normal'), layer:allowed('layer',['results','inputs'],'results'), method:allowed('method',Object.keys(methods),'swiss'), body:allowed('body',['R1','S1','R2','C1','D1','W1'],'R2'), landscape:allowed('landscape',['landscape','network'],'landscape'), month:Math.max(0,Math.min(11,params.has('month')&&Number.isFinite(Number(params.get('month')))?Number(params.get('month')):5)), detail:params.get('detail')==='open'};
const main = document.getElementById('main');
function save(){const p=new URLSearchParams();for(const [key,value] of Object.entries(state))p.set(key,key==='detail'?(value?'open':'closed'):String(value));history.replaceState(null,'',`${location.pathname}?${p}`);}
function segmented(key, entries){return `<div class="switch" role="group" aria-label="${key==='forcing'?'Illustrative inflow scenario':key==='layer'?'Chart layer':key==='operation'?'Allocation priority':'System representation'}">${entries.map(([value,label])=>`<button data-set="${key}" data-value="${value}" aria-pressed="${state[key]===value}">${label}</button>`).join('')}</div>`;}
const bodies={R1:['Upstream river','Natural origin','Natural/status route','Water-body extent upstream of intake.'],S1:['Reservoir','Modified natural location','Designation evidence pending','Storage feature; classification cannot be inferred from this schematic alone.'],R2:['Downstream river','Natural origin','Natural/status route','R2a and R2b are model reaches of one illustrative water body.'],C1:['Irrigation canal','Artificial origin','Potential/service route','Carries diverted water to fields on the valley floor.'],D1:['Drainage return','Artificial origin','Potential/service route','Returns downstream of the reservoir; quantity and quality need separate assessment.'],W1:['Valley wetland','Natural receptor','State-target assessment','Supply pathways are unknown. No drain or groundwater connection is asserted.']};
const assessmentRecords={
  R1:{route:'Natural/status route; tier not yet selected.',computed:'Upstream water routing only; no ecological delivery assessment.',pending:'Accepted natural reference, local pressures and ecological objectives.',next:'Basin team: assemble evidence; NCECC: review the assessment basis.'},
  R2:{route:'Natural/status route; the buttons compare components, not eligibility decisions.',computed:'Modelled delivery and conservative salt at R2a and R2b.',pending:'Accepted reference, complete regime and local ecological evidence.',next:'Basin team and specialists: complete the evidence; NCECC: review the proposed requirement.'},
  S1:{route:'Natural/status by default for this modified natural location; potential requires valid designation.',computed:'Storage, release and spill in the hypothetical network.',pending:'Designation evidence, reservoir level/shoreline objectives and operating duties.',next:'Basin team and operator: document conditions; competent authority: decide designation.'},
  C1:{route:'Artificial-water potential/service route.',computed:'Irrigation diversion and supply; no ecological assessment.',pending:'Protected functions, service objectives and water-quality requirements.',next:'Operator and basin team: document functions; NCECC: review proposed protection objectives.'},
  D1:{route:'Artificial-water potential/service route.',computed:'Assumed 50% same-day return; conservative salt transport is assessed separately.',pending:'Return timing, water quality and protected functions.',next:'Operator and basin team: measure returns and quality; NCECC: review protection objectives.'},
  W1:{route:'Wetland state targets: water level, seasonal wetness and quality.',computed:'No water supply or ecological status calculated.',pending:'Surface/groundwater connections and ecological water-level needs.',next:'Wetland and groundwater specialists: establish connections and targets for NCECC review.'}
};
function assessmentRecord(){const r=assessmentRecords[state.body];return `<div class="assessment-record"><h3>Assessment basis</h3><dl class="record-list"><dt>Route</dt><dd>${r.route}</dd><dt>Calculated here</dt><dd>${r.computed}</dd><dt>Still needed</dt><dd>${r.pending}</dd><dt>Next step · proposed</dt><dd>${r.next}</dd></dl></div>`;}
function networkFigure(){return `<svg class="system-figure" viewBox="0 0 920 440" role="img" aria-label="Network abstraction at the same positions. Inlet R1 to intake, S1 storage, R2a and R2b outlet. Intake to C1, irrigation, D1, returning at R2b. W1 has no confirmed connection."><defs><marker id="net-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5L0 10Z" fill="#38858e"/></marker></defs><rect width="920" height="440" fill="#f8faf6"/><text x="30" y="42">Model representation · same locations and IDs</text><path d="M95 145L229 283" stroke="#38858e" stroke-width="3" fill="none" marker-end="url(#net-arrow)"/><path d="M239 287H331" stroke="#38858e" stroke-width="3" fill="none" marker-end="url(#net-arrow)"/><path d="M429 287H539" stroke="#38858e" stroke-width="3" fill="none" marker-end="url(#net-arrow)"/><path d="M543 287H681" stroke="#38858e" stroke-width="3" fill="none" marker-end="url(#net-arrow)"/><path d="M693 287H862" stroke="#38858e" stroke-width="3" fill="none" marker-end="url(#net-arrow)"/><path d="M235 281L294 211H396" stroke="#38858e" stroke-width="3" fill="none" marker-end="url(#net-arrow)"/><path d="M569 211L635 243L682 283" stroke="#38858e" stroke-width="3" fill="none" marker-end="url(#net-arrow)"/><rect x="335" y="260" width="90" height="54" rx="4" fill="#e0eeeb" stroke="#38858e" stroke-width="2"/><text x="380" y="282" text-anchor="middle">S1</text><text x="380" y="300" text-anchor="middle" style="font-size:12px">Storage</text><rect x="400" y="181" width="165" height="60" rx="4" fill="#edf0e1" stroke="#98a37d" stroke-width="2"/><text x="482" y="216" text-anchor="middle">Irrigation</text><rect x="701" y="116" width="130" height="54" rx="4" fill="#f4f6ef" stroke="#93b49b" stroke-dasharray="5 4"/><text x="766" y="148" text-anchor="middle">W1 · wetland</text><text x="679" y="192" style="font-size:13px">Supply pathways unknown</text><circle cx="233" cy="287" r="5" fill="#193c40"/><circle cx="687" cy="287" r="5" fill="#193c40"/><text x="67" y="123" style="font-size:13px">Inlet boundary</text><text x="117" y="226">R1</text><text x="273" y="186">C1 · canal</text><text x="600" y="213">D1 · return</text><text x="209" y="324" style="font-size:13px">Intake</text><text x="487" y="323">R2a</text><text x="731" y="323">R2b</text><text x="821" y="255" style="font-size:13px">Outlet</text><path d="M810 265V307" stroke="#193c40" stroke-width="3"/><circle cx="810" cy="287" r="6" fill="#fffefa" stroke="#193c40" stroke-width="2"/><text x="770" y="350" style="font-size:12px">Calculation section</text><path d="M438 354V369H863V354" fill="none" stroke="#8b9c85"/><text x="638" y="394" text-anchor="middle">R2 · one illustrative water body</text><text x="30" y="418" style="font-size:11px">Junction dots connect model elements; they are not water bodies.</text>${state.body==='R2'?'<path d="M432 287H865" stroke="#193c40" stroke-width="20" opacity=".14" stroke-linecap="round"/>':state.body==='S1'?'<rect x="330" y="255" width="100" height="64" fill="none" stroke="#193c40" stroke-width="4" opacity=".3"/>':state.body==='W1'?'<rect x="696" y="111" width="140" height="64" fill="none" stroke="#193c40" stroke-width="4" opacity=".3"/>':`<path d="${{R1:'M95 145L233 287',C1:'M233 287L294 211H400',D1:'M565 211L635 243L687 287'}[state.body]}" fill="none" stroke="#193c40" stroke-width="20" opacity=".14" stroke-linecap="round"/>`}</svg>`;}
function systemFigure(){const land=state.landscape==='landscape'; if(!land)return networkFigure(); const highlight={R1:'M95 145Q130 180 183 220L233 286',S1:'M335 287H425',R2:'M425 287H846',C1:'M233 286L294 211L400 211',D1:'M565 211L635 243L687 287',W1:'M711 145H820'}[state.body];return `<svg class="system-figure" viewBox="0 0 920 440" role="img" aria-label="${land?'Valley landscape':'Network abstraction'}. R1 to intake, reservoir S1, R2a then R2b. Intake branches through C1 canal, fields, D1 drain to R2b. Wetland supply unknown."><defs><marker id="blue-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5L0 10Z" fill="#38858e"/></marker><marker id="brown-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5L0 10Z" fill="#a7854d"/></marker></defs><rect width="920" height="440" fill="${land?'#f5f5e9':'#f8faf6'}"/>${land?'<path d="M0 180L80 50L146 155L181 90L270 204Z" fill="#c8d1c0"/><path d="M48 102L80 50L111 101L87 94L75 105Z" fill="#fffefa"/><path d="M0 213Q260 145 920 177V440H0Z" fill="#e8eddb"/><path d="M0 358Q380 320 920 357" stroke="#d8e1c8" fill="none" stroke-width="20"/>':'<text x="30" y="42">Same locations and connections · features abstracted</text>'}<path d="M95 145Q130 180 183 220L233 286H335M425 287H846" stroke="#c1dfdf" stroke-width="17" fill="none"/><path d="M95 145Q130 180 183 220L233 286H335M425 287H535M535 287H687M687 287H846" stroke="#38858e" stroke-width="5" fill="none" marker-end="url(#blue-arrow)"/><rect x="335" y="263" width="90" height="48" rx="15" fill="#a3ced1" stroke="#38858e" stroke-width="2"/><path d="M233 286L294 211H400" stroke="#a7854d" stroke-width="5" fill="none" marker-end="url(#brown-arrow)"/><rect x="400" y="171" width="165" height="76" rx="5" fill="#d4dfb7" stroke="#9eac7f"/>${[421,444,467,490,513,536].map(x=>`<path d="M${x} 183V234" stroke="#b1c18e" stroke-width="3"/>`).join('')}<path d="M565 211L635 243L687 287" stroke="#a7854d" stroke-width="5" fill="none" marker-end="url(#brown-arrow)"/><ellipse cx="766" cy="142" rx="65" ry="27" fill="#c6d9c1" stroke="#93b49b" stroke-dasharray="5 4"/><path d="M733 142V122M747 147V124M763 143V117M781 147V125" stroke="#7ca07d" stroke-width="3"/><text x="717" y="94">W1 · wetland</text><text x="679" y="190" style="font-size:13px">Supply pathways unknown</text><text x="111" y="209">R1 · river</text><text x="303" y="185">C1 · canal</text><text x="482" y="269" text-anchor="middle" style="font-size:13px">Irrigated fields</text><text x="611" y="218">D1 · drain</text><text x="335" y="339">S1 · reservoir</text><text x="481" y="323">R2a</text><text x="730" y="323">R2b</text><circle cx="233" cy="286" r="5" fill="#294f50"/><text x="204" y="325" style="font-size:13px">Intake</text><path d="M810 266V306" stroke="#183d42" stroke-width="3"/><circle cx="810" cy="287" r="6" fill="#fffefa" stroke="#183d42" stroke-width="2"/><text x="775" y="356" style="font-size:13px">Calculation section</text><path d="M438 352V366H847V352" stroke="#8b9c85" fill="none"/><text x="625" y="392" text-anchor="middle">R2 · one illustrative water body</text><path d="${highlight}" fill="none" stroke="#183d42" stroke-width="26" stroke-linecap="round" opacity=".17"/><text x="30" y="418" style="font-size:11px">${land?'Mountains upstream · canals and drainage on the flat valley floor':'Lines represent connected physical features; junctions are not water bodies'}</text></svg>`;}
function system(){const b=bodies[state.body];return `<div class="title-row"><div><p class="eyebrow">System</p><h1>From landscape to assessment object</h1></div>${segmented('landscape',[['landscape','Landscape'],['network','Network']])}</div><div class="system-layout"><section class="panel"><div class="svg-wrap" tabindex="0" role="region" aria-label="System illustration, scroll horizontally on narrow screens">${systemFigure()}</div><div class="body-picks" role="group" aria-label="Inspect water body">${Object.keys(bodies).map(id=>`<button data-set="body" data-value="${id}" aria-pressed="${state.body===id}">${id} · ${bodies[id][0]}</button>`).join('')}</div><p class="system-caption">Illustrative extents, not a surveyed map. A calculation section is where flow is calculated or assessed; it is not a separate water body.</p></section><aside class="panel side-card"><p class="eyebrow">Selected object</p><h2>${state.body} · ${b[0]}</h2><span class="body-type">${b[1]}</span><p class="detail-copy">${b[3]}</p>${assessmentRecord()}<p class="small-note">Selecting a feature opens its record. The comparison remains at R2: R2a before drainage returns, R2b after them.</p><button class="plain-button" data-view="compare">Back to method comparison →</button></aside></div>`;}
function render(){document.querySelectorAll('nav [data-view]').forEach(b=>b.setAttribute('aria-current',state.view===b.dataset.view?'page':'false'));main.innerHTML=state.view==='route'?RouteView.render(PrototypeLocale.language,state.body):state.view==='compare'?compare():state.view==='system'?system():assessment();PrototypeLocale.apply();save();globalThis.RetainedNavigation?.refresh();}
globalThis.RouteView?.connect(render);
document.addEventListener('click',e=>{const view=e.target.closest('[data-view]');const set=e.target.closest('[data-set]');const method=e.target.closest('[data-method]');if(view){state.view=view.dataset.view;render();}else if(set){state[set.dataset.set]=set.dataset.value;render();}else if(method){state.method=method.dataset.method;state.detail=true;render();}else if(e.target.closest('[data-close]')){state.detail=false;render();}});
document.addEventListener('input',e=>{if(e.target.id==='month'){state.month=Number(e.target.value);const focused=e.target;const value=focused.value;render();const replacement=document.getElementById('month');replacement.focus();replacement.value=value;}});

document.addEventListener('change',e=>{if(e.target.id==='fixed-target'){state.basis=e.target.checked?'fixed':'matched';render();}});

document.addEventListener('change',e=>{if(e.target.id==='language'){state.lang=PrototypeLocale.setLanguage(e.target.value);render();}});
